import { NO_MESSAGE_HANDLER, REDIS_DEFAULT_HOST, REDIS_DEFAULT_PORT, } from '../constants.js';
import { RedisContext } from '../ctx-host/index.js';
import { Transport } from '../enums/index.js';
import { MaxRedisChannelLengthExceededException } from '../errors/max-redis-channel-length-exceeded.exception.js';
import { Server } from './server.js';
import { isNil, isUndefined } from '@nestjs/common/internal';
const DEFAULT_MAX_WILDCARD_CHANNEL_LENGTH = 1024;
/**
 * @publicApi
 */
export class ServerRedis extends Server {
    options;
    transportId = Transport.REDIS;
    subClient;
    pubClient;
    isManuallyClosed = false;
    wasInitialConnectionSuccessful = false;
    pendingEventListeners = [];
    constructor(options) {
        super();
        this.options = options;
        this.initializeSerializer(options);
        this.initializeDeserializer(options);
    }
    async listen(callback) {
        try {
            this.subClient = await this.createRedisClient();
            this.pubClient = await this.createRedisClient();
            // A close() before this listen() must not keep retries off for good.
            // Set once the replacement clients exist, so an old client cannot report
            // its own "end" through the flag while the swap is in progress
            this.isManuallyClosed = false;
            [this.subClient, this.pubClient].forEach((client, index) => {
                const type = index === 0 ? 'sub' : 'pub';
                this.registerErrorListener(client);
                this.registerReconnectListener(client);
                this.registerReadyListener(client);
                this.registerEndListener(client);
                this.pendingEventListeners.forEach(({ event, callback }) => client.on(event, (...args) => callback(type, ...args)));
            });
            this.pendingEventListeners = [];
            this.start(callback);
        }
        catch (err) {
            callback(err);
        }
    }
    start(callback) {
        void Promise.all([this.subClient.connect(), this.pubClient.connect()])
            .then(() => this.bindEvents(this.subClient, this.pubClient))
            .then(() => callback?.())
            .catch(callback);
    }
    async bindEvents(subClient, pubClient) {
        subClient.on(this.options?.wildcards ? 'pmessage' : 'message', this.getMessageHandler(pubClient).bind(this));
        const subscribePatterns = [...this.messageHandlers.keys()];
        // Awaited so that a rejected subscription (e.g., an ACL without access to
        // the channel) fails `listen()` instead of going unhandled.
        await Promise.all(subscribePatterns.map(pattern => {
            const { isEventHandler } = this.messageHandlers.get(pattern);
            const channel = isEventHandler
                ? pattern
                : this.getRequestPattern(pattern);
            return this.options?.wildcards
                ? subClient.psubscribe(channel)
                : subClient.subscribe(channel);
        }));
    }
    async close() {
        this.isManuallyClosed = true;
        if (this.getOptionsProp(this.options, 'gracefulShutdown')) {
            await this.stopReceivingMessages();
            await this.waitForHandlersInFlight(this.getOptionsProp(this.options, 'gracePeriod'));
        }
        this.pubClient && (await this.quitClient(this.pubClient));
        this.subClient && (await this.quitClient(this.subClient));
        this.pendingEventListeners = [];
    }
    // The connections stay open, as the handlers in flight publish their
    // replies through them.
    async stopReceivingMessages() {
        if (!this.subClient) {
            return;
        }
        try {
            await (this.options?.wildcards
                ? this.subClient.punsubscribe()
                : this.subClient.unsubscribe());
        }
        catch {
            // The command cannot be sent, so the subscriber is not connected and
            // receives nothing either way.
        }
    }
    // `quit()` rejects when the command cannot be sent (e.g., while
    // reconnecting with the offline queue disabled), which would leave the
    // other client open. Close the connection right away instead.
    async quitClient(client) {
        try {
            await client.quit();
        }
        catch {
            client.disconnect();
        }
    }
    async createRedisClient() {
        const clientInfoTag = this.getOptionsProp(this.options, 'clientInfoTag');
        const redisPackage = await this.loadPackage('ioredis', ServerRedis.name, () => import('ioredis'));
        const RedisClient = redisPackage.default || redisPackage;
        return new RedisClient({
            port: REDIS_DEFAULT_PORT,
            host: REDIS_DEFAULT_HOST,
            ...this.getClientOptions(),
            ...(clientInfoTag && { clientInfoTag }),
            lazyConnect: true,
        });
    }
    getMessageHandler(pub) {
        return this.options?.wildcards
            ? (channel, pattern, buffer) => this.handleMessage(channel, buffer, pub, pattern).catch(err => this.handleError(err))
            : (channel, buffer) => this.handleMessage(channel, buffer, pub, channel).catch(err => this.handleError(err));
    }
    async handleMessage(channel, buffer, pub, pattern) {
        const rawMessage = this.parseMessage(buffer);
        if (this.options?.wildcards &&
            this.isOwnReply(channel, pattern, rawMessage)) {
            return;
        }
        const packet = await this.deserializer.deserialize(rawMessage, { channel });
        const redisCtx = new RedisContext([pattern, packet.metadata]);
        if (isUndefined(packet.id)) {
            return this.handleEvent(channel, packet, redisCtx);
        }
        this.assertValidPacketId(packet.id);
        this.assertWildcardChannelLength(channel, pattern);
        // With wildcards, `channel` is the subscribed pattern (e.g. "users.*") and
        // `pattern` is the concrete channel the request was published to. The
        // client waits for the reply on the concrete one, so reply there.
        const publish = this.getPublisher(pub, pattern, packet.id, redisCtx);
        const handler = this.getHandlerByPattern(channel);
        if (!handler) {
            const status = 'error';
            const noHandlerPacket = {
                id: packet.id,
                status,
                err: NO_MESSAGE_HANDLER,
            };
            return publish(noHandlerPacket);
        }
        if (handler.isEventHandler && this.isAnsweredByMessageHandler(pattern)) {
            // Redis delivers the request to every subscribed pattern that matches
            // its channel, so the message handler subscribed to it answers it.
            return this.handleEvent(channel, packet, redisCtx);
        }
        if (channel !== pattern && this.isAnsweredByMessageHandler(pattern)) {
            // The message handler subscribed to the channel itself answers it alone
            return;
        }
        this.warnIfEventHandlerReplies(handler, channel);
        return this.handleRequest(redisCtx, async () => this.transformToObservable(await handler(packet.data, redisCtx)), publish);
    }
    /**
     * With wildcards, the sender of a request chooses the channel it publishes
     * the request to among those a pattern matches, and "*" matches a run of
     * any length. Every reply is published on a copy of that channel
     * ("<channel>.reply"), as many times as the handler emits.
     */
    assertWildcardChannelLength(subscription, channel) {
        const option = this.getOptionsProp(this.options, 'maxWildcardChannelLength');
        // A value that is not a number (NaN, "1kb") gets the default limit
        // rather than none
        const maxLength = isNil(option) || isNaN(option)
            ? DEFAULT_MAX_WILDCARD_CHANNEL_LENGTH
            : option;
        if (channel !== subscription &&
            maxLength > 0 &&
            channel.length > maxLength) {
            throw new MaxRedisChannelLengthExceededException(channel.length, maxLength);
        }
    }
    /**
     * With wildcards, whether a message handler is subscribed to the channel a
     * request was published to as well. Only a subscription to that very
     * channel is found: Redis' glob-style matching is not reproduced here.
     */
    isAnsweredByMessageHandler(channel) {
        if (!this.options?.wildcards) {
            return false;
        }
        return [...this.messageHandlers].some(([pattern, handler]) => !handler.isEventHandler && this.getRequestPattern(pattern) === channel);
    }
    /**
     * With wildcards, a subscription such as "users.*" also matches the channels
     * this server replies on ("users.created.reply"). Those replies are skipped
     * unless the subscription itself targets reply channels.
     */
    isOwnReply(subscription, channel, message) {
        const replySuffix = this.getReplyPattern('');
        return (channel.endsWith(replySuffix) &&
            !subscription.endsWith(replySuffix) &&
            !isUndefined(message?.id) &&
            isUndefined(message?.pattern));
    }
    getPublisher(pub, pattern, id, ctx) {
        return (response) => {
            Object.assign(response, { id });
            const outgoingResponse = this.serializer.serialize(response);
            return pub.publish(this.getReplyPattern(pattern), JSON.stringify(outgoingResponse));
        };
    }
    parseMessage(content) {
        try {
            return JSON.parse(content);
        }
        catch (e) {
            return content;
        }
    }
    getRequestPattern(pattern) {
        return pattern;
    }
    getReplyPattern(pattern) {
        return `${pattern}.reply`;
    }
    registerErrorListener(client) {
        client.on("error" /* RedisEventsMap.ERROR */, (err) => this.logger.error(err));
    }
    registerReconnectListener(client) {
        client.on("reconnecting" /* RedisEventsMap.RECONNECTING */, () => {
            if (this.isManuallyClosed) {
                return;
            }
            this._status$.next("reconnecting" /* RedisStatus.RECONNECTING */);
            if (this.wasInitialConnectionSuccessful) {
                this.logger.log('Reconnecting to Redis...');
            }
        });
    }
    registerReadyListener(client) {
        client.on("ready" /* RedisEventsMap.READY */, () => {
            this._status$.next("connected" /* RedisStatus.CONNECTED */);
            this.logger.log('Connected to Redis. Subscribing to channels...');
            if (!this.wasInitialConnectionSuccessful) {
                this.wasInitialConnectionSuccessful = true;
            }
        });
    }
    registerEndListener(client) {
        client.on('end', () => {
            if (this.isManuallyClosed ||
                // The "end" of a client a newer "listen" replaced: quit() resolves
                // before ioredis emits "end", so this can arrive while the
                // replacement clients are already connected
                ![this.subClient, this.pubClient].includes(client)) {
                return;
            }
            this._status$.next("disconnected" /* RedisStatus.DISCONNECTED */);
            this.logger.error('Disconnected from Redis. No further reconnection attempts will be made.');
        });
    }
    getClientOptions() {
        const retryStrategy = (times) => this.createRetryStrategy(times);
        return {
            ...(this.options || {}),
            retryStrategy,
        };
    }
    createRetryStrategy(times) {
        if (this.isManuallyClosed) {
            return undefined;
        }
        if (!this.getOptionsProp(this.options, 'retryAttempts')) {
            this.logger.error('Redis connection closed and retry attempts not specified');
            return;
        }
        if (times > this.getOptionsProp(this.options, 'retryAttempts', 0)) {
            this.logger.error(`Retry time exhausted`);
            return;
        }
        return this.getOptionsProp(this.options, 'retryDelay', 5000);
    }
    unwrap() {
        if (!this.pubClient || !this.subClient) {
            throw new Error('Not initialized. Please call the "listen"/"startAllMicroservices" method before accessing the server.');
        }
        return [this.pubClient, this.subClient];
    }
    on(event, callback) {
        if (this.subClient && this.pubClient) {
            this.subClient.on(event, (...args) => callback('sub', ...args));
            this.pubClient.on(event, (...args) => callback('pub', ...args));
        }
        else {
            this.pendingEventListeners.push({ event, callback });
        }
    }
}
